     }
@@ -126,51 +129,111 @@ void SlidingPopupsEffect::prePaintWindow(RenderView *view, EffectWindow *w, Wind
 bool SlidingPopupsEffect::paintWindow(const RenderTarget &renderTarget, const RenderViewport &viewport, EffectWindow *w, int mask, const Region &deviceGeometry, WindowPaintData &data)
 {
     auto animationIt = m_animations.find(w);
-    if (animationIt == m_animations.end()) {
+    const QPointF panelTranslation = panelSlideTranslation(w);
+    if (animationIt == m_animations.end() && panelTranslation.isNull()) {
         return effects->paintWindow(renderTarget, viewport, w, mask, deviceGeometry, data);
     }

     const AnimationData &animData = m_animationsData[w];
-    const qreal slideLength = (animData.slideLength > 0) ? animData.slideLength : m_slideLength;
+    if (animationIt != m_animations.end()) {
+        const qreal slideLength = (animData.slideLength > 0) ? animData.slideLength : m_slideLength;
+        const RectF geo = w->expandedGeometry();
+        const bool horizontal = animData.location == Location::Left || animData.location == Location::Right;
+        if (slideLength < (horizontal ? geo.width() : geo.height())) {
+            data.multiplyOpacity(animationIt->second.timeLine.value());
+        }
+    }
+    const QPointF translation = slideTranslation(w) + panelTranslation;
+    data.translate(translation.x(), translation.y());

+    Region effectiveRegion = deviceGeometry;
+    effectiveRegion &= viewport.mapToDeviceCoordinatesAligned(damagedLogicalArea(w, animData));
+
+    return effects->paintWindow(renderTarget, viewport, w, mask, effectiveRegion, data);
+}
+
+QPointF SlidingPopupsEffect::slideTranslation(EffectWindow *w) const
+{
+    const auto animationIt = m_animations.find(w);
+    if (animationIt == m_animations.end()) {
+        return QPointF();
+    }
+
+    const AnimationData animData = m_animationsData.value(w);
+    const qreal slideLength = (animData.slideLength > 0) ? animData.slideLength : m_slideLength;
     const RectF geo = w->expandedGeometry();
     const qreal t = animationIt->second.timeLine.value();

-    Region effectiveRegion = deviceGeometry;
     switch (animData.location) {
     case Location::Left:
-        if (slideLength < geo.width()) {
-            data.multiplyOpacity(t);
-        }
-        data.translate(-interpolate(std::min(geo.width(), slideLength), 0.0, t));
-        break;
+        return QPointF(-interpolate(std::min(geo.width(), slideLength), 0.0, t), 0.0);
     case Location::Top:
-        if (slideLength < geo.height()) {
-            data.multiplyOpacity(t);
-        }
-        data.translate(0.0, -interpolate(std::min(geo.height(), slideLength), 0.0, t));
-        break;
+        return QPointF(0.0, -interpolate(std::min(geo.height(), slideLength), 0.0, t));
     case Location::Right:
-        if (slideLength < geo.width()) {
-            data.multiplyOpacity(t);
-        }
-        data.translate(interpolate(std::min(geo.width(), slideLength), 0.0, t));
-        break;
+        return QPointF(interpolate(std::min(geo.width(), slideLength), 0.0, t), 0.0);
     case Location::Bottom:
     default:
-        if (slideLength < geo.height()) {
-            data.multiplyOpacity(t);
-        }
-        data.translate(0.0, interpolate(std::min(geo.height(), slideLength), 0.0, t));
+        return QPointF(0.0, interpolate(std::min(geo.height(), slideLength), 0.0, t));
     }
+}

-    effectiveRegion &= viewport.mapToDeviceCoordinatesAligned(damagedLogicalArea(w, animData));
+QPointF SlidingPopupsEffect::panelSlideTranslation(EffectWindow *w) const
+{
+    // Popups that slide out of a panel which is sliding in from the same edge, such as an auto-hide panel
+    // being revealed, move along with it, so they don't detach from it during the animation
+    const auto dataIt = m_animationsData.constFind(w);
+    if (dataIt == m_animationsData.constEnd() || w->isDock()) {
+        return QPointF();
+    }

-    return effects->paintWindow(renderTarget, viewport, w, mask, effectiveRegion, data);
+    const RectF screenRect = effects->clientArea(FullScreenArea, w->screen());
+    const RectF geo = w->frameGeometry();
+    for (const auto &[panel, animation] : m_animations) {
+        const auto panelDataIt = m_animationsData.constFind(panel);
+        if (!panel->isDock() || panel->screen() != w->screen() || panelDataIt == m_animationsData.constEnd() || panelDataIt->location != dataIt->location) {
+            continue;
+        }
+        const RectF panelGeo = panel->frameGeometry();
+        bool slidesOutOfPanel = false;
+        switch (dataIt->location) {
+        case Location::Left: {
+            const qreal edge = screenRect.left() + dataIt->offset;
+            slidesOutOfPanel = edge >= panelGeo.left() && edge <= panelGeo.right() && geo.top() < panelGeo.bottom() && geo.bottom() > panelGeo.top();
+            break;
+        }
+        case Location::Top: {
+            const qreal edge = screenRect.top() + dataIt->offset;
+            slidesOutOfPanel = edge >= panelGeo.top() && edge <= panelGeo.bottom() && geo.left() < panelGeo.right() && geo.right() > panelGeo.left();
+            break;
+        }
+        case Location::Right: {
+            const qreal edge = screenRect.right() - dataIt->offset;
+            slidesOutOfPanel = edge >= panelGeo.left() && edge <= panelGeo.right() && geo.top() < panelGeo.bottom() && geo.bottom() > panelGeo.top();
+            break;
+        }
+        case Location::Bottom:
+        default: {
+            const qreal edge = screenRect.bottom() - dataIt->offset;
+            slidesOutOfPanel = edge >= panelGeo.top() && edge <= panelGeo.bottom() && geo.left() < panelGeo.right() && geo.right() > panelGeo.left();
+            break;
+        }
+        }
+        if (slidesOutOfPanel) {
+            return slideTranslation(panel);
+        }
+    }
+    return QPointF();
 }

 void SlidingPopupsEffect::postPaintScreen()
 {
+    for (auto dataIt = m_animationsData.cbegin(); dataIt != m_animationsData.cend(); ++dataIt) {
+        EffectWindow *w = const_cast<EffectWindow *>(dataIt.key());
+        if (!m_animations.contains(w) && !panelSlideTranslation(w).isNull()) {
+            effects->addRepaint(damagedLogicalArea(w, *dataIt));
+        }
+    }
+
     for (auto animationIt = m_animations.begin(); animationIt != m_animations.end();) {
         EffectWindow *w = animationIt->first;
         const AnimationData &animData = m_animationsData[w];
@@ -395,21 +458,27 @@ RectF SlidingPopupsEffect::damagedLogicalArea(EffectWindow *w, const AnimationDa
     const RectF screenRect = effects->clientArea(FullScreenArea, w->screen());
     const RectF geo = w->expandedGeometry();

+    RectF area;
     switch (animData.location) {
     case Location::Left:
-        return RectF(QPointF(screenRect.left() + animData.offset, geo.top()),
+        area = RectF(QPointF(screenRect.left() + animData.offset, geo.top()),
                      QPointF(geo.right(), geo.bottom()));
+        break;
     case Location::Top:
-        return RectF(QPointF(geo.left(), screenRect.top() + animData.offset),
+        area = RectF(QPointF(geo.left(), screenRect.top() + animData.offset),
                      QPointF(geo.right(), geo.bottom()));
+        break;
     case Location::Right:
-        return RectF(QPointF(geo.left(), geo.top()),
+        area = RectF(QPointF(geo.left(), geo.top()),
                      QPointF(screenRect.right() - animData.offset, geo.bottom()));
+        break;
     case Location::Bottom:
     default:
-        return RectF(QPointF(geo.left(), geo.top()),
+        area = RectF(QPointF(geo.left(), geo.top()),
                      QPointF(geo.right(), screenRect.bottom() - animData.offset));
+        break;
     }
+    return area | area.translated(panelSlideTranslation(w));
 }

 bool SlidingPopupsEffect::eventFilter(QObject *watched, QEvent *event)
